($$apresentacao-maria$$, $$Apresentação de Nossa Senhora$$, $$Maria no Templo$$, $$21 de Novembro$$, 11, 21, $$$$, $$$$, '{"Vida consagrada"}'::text[], $$Festa que celebra a tradição da apresentação da Virgem Maria no Templo de Jerusalém pelos seus pais.$$, $$Festa que celebra a tradição da apresentação da Virgem Maria no Templo de Jerusalém pelos seus pais.$$, $$[]$$::jsonb, '{"\"Desde a infância, Maria se consagrou totalmente a Deus.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Titian_-_Presentation_of_the_Virgin_at_the_Temple_%28detail%29_-_WGA22782.jpg/440px-Titian_-_Presentation_of_the_Virgin_at_the_Temple_%28detail%29_-_WGA22782.jpg$$, $$$$, '{"Consagração"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$cecilia$$, $$Santa Cecília$$, $$Padroeira da Música$$, $$22 de Novembro$$, 11, 22, $$Séc. II, Roma$$, $$230, Roma$$, '{"Músicos","Poetas"}'::text[], $$Virgem e mártir romana, padroeira dos músicos por ter cantado a Deus em seu coração durante seu casamento forçado.$$, $$Virgem e mártir romana, padroeira dos músicos por ter cantado a Deus em seu coração durante seu casamento forçado.$$, $$[]$$::jsonb, '{"\"Cantai ao Senhor um cântico novo.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Guido_Reni_-_Saint_Cecilia_-_Google_Art_Project.jpg/440px-Guido_Reni_-_Saint_Cecilia_-_Google_Art_Project.jpg$$, $$$$, '{"Música","Pureza"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
