($$francisco-xavier$$, $$São Francisco Xavier$$, $$Apóstolo do Oriente$$, $$3 de Dezembro$$, 12, 3, $$1506, Navarra$$, $$1552, Ilha de Sanchoão$$, '{"Missionários","Turismo"}'::text[], $$Jesuíta co-fundador, missionário nas Índias, Malásia e Japão. Batizou mais de 30 mil pessoas.$$, $$Jesuíta co-fundador, missionário nas Índias, Malásia e Japão. Batizou mais de 30 mil pessoas.$$, $$[]$$::jsonb, '{"\"Quantas almas deixam de ir ao Céu por falta de quem as ensine!\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Fran%C3%A7ois-Xavier.jpg/440px-Fran%C3%A7ois-Xavier.jpg$$, $$$$, '{"Missão","Zelo"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$barbara$$, $$Santa Bárbara$$, $$Protetora contra Raios$$, $$4 de Dezembro$$, 12, 4, $$Séc. III, Nicomédia$$, $$306, Nicomédia$$, '{"Artilheiros","Mineradores","Bombeiros"}'::text[], $$Virgem e mártir presa numa torre por seu pai pagão. Converteu-se ao cristianismo e foi decapitada pelo próprio pai.$$, $$Virgem e mártir presa numa torre por seu pai pagão. Converteu-se ao cristianismo e foi decapitada pelo próprio pai.$$, $$[]$$::jsonb, '{"\"Cristo é minha fortaleza e minha torre.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Robert_Campin_-_Saint_Barbara_-_Google_Art_Project.jpg/440px-Robert_Campin_-_Saint_Barbara_-_Google_Art_Project.jpg$$, $$$$, '{"Fortaleza","Fé"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
